function redirectToPlayer(){const currentParams=new URLSearchParams(window.location.search),playerUrlObj=new URL("player.html",window.location.origin),statusElement=document.getElementById("redirect-status"),manualRedirect=document.getElementById("manual-redirect");currentParams.forEach((value,key)=>{playerUrlObj.searchParams.set(key,value)});const referrer=document.referrer,backUrl=currentParams.get("back");let returnUrl="";backUrl?returnUrl=decodeURIComponent(backUrl):referrer&&(referrer.includes("/s=")||referrer.includes("?s="))||referrer&&referrer.trim()!==""?returnUrl=referrer:returnUrl="/",playerUrlObj.searchParams.has("returnUrl")||playerUrlObj.searchParams.set("returnUrl",encodeURIComponent(returnUrl)),localStorage.setItem("lastPageUrl",returnUrl),(returnUrl.includes("/s=")||returnUrl.includes("?s="))&&(localStorage.setItem("cameFromSearch","true"),localStorage.setItem("searchPageUrl",returnUrl));const finalPlayerUrl=playerUrlObj.toString();manualRedirect&&(manualRedirect.href=finalPlayerUrl),statusElement&&(statusElement.textContent="\u5373\u5C06\u5F00\u59CB\u64AD\u653E..."),window.location.replace(finalPlayerUrl)}try{redirectToPlayer()}catch(error){console.error("\u64AD\u653E\u5668\u8DF3\u8F6C\u5931\u8D25:",error);const statusElement=document.getElementById("redirect-status");statusElement&&(statusElement.textContent="\u81EA\u52A8\u8DF3\u8F6C\u5931\u8D25\uFF0C\u8BF7\u70B9\u51FB\u4E0B\u65B9\u94FE\u63A5\u7EE7\u7EED")}
